import React = require('react');

export default React.createClass<any, any>({

    getInitialState() {
        return {};
    },

    componentWillMount() {
        this.showCameraView = false;
        document.addEventListener('click', (event) => {
            for (let target:any = event.target; target != document.body; ) {
                if (target && target.id && target.id == 'viewTrigger') {
                    return;
                }
                if (!target.parentNode) {
                    break;
                }
                target = target.parentNode;
            }
            this.setShowCameraViewPopup(false);
        });
    },

    onCameraSelected(value) {
        this.props.setCamera(value.target.id);
        this.toggleCameraViewPicker();
    },

    toggleCameraViewPicker() {
        this.showCameraView = !this.showCameraView;
        this.forceUpdate();
    },

    selectMode(event) {
        this.mode = event.target.id;
        this.props.setMode(this.mode);
    },

    setShowCameraViewPopup(doShow) {
        this.showCameraView = doShow;
        this.forceUpdate();
    },

    render() {
        let showView = this.showCameraView ? "show" : "hide";
        let viewEnabled = this.showCameraView ? "selected" : "unselected";

        let audioMode = this.mode === "audio" ? "selected" : "unselected";
        let targetMode = this.mode === "target" ? "selected" : "unselected";

        return <div>
                    <div className="tools-top">
                        <button id="audio" className={"top main " + audioMode} onClick={this.selectMode}>
                            <span id="audio" className="fa fa-microphone icon"></span>
                        </button>
                        <button id="target" className={"top main " + targetMode} onClick={this.selectMode}>
                            <span id="target" className="fa fa-dot-circle-o icon"></span>
                        </button>
                    </div>
                    <div className="tools-bottom">
                        <button id="viewTrigger" className={"bottom main " + viewEnabled} onClick={this.toggleCameraViewPicker}>
                            <span className="fa fa-video-camera icon"></span>
                        </button>
                        <div className={"popup  " + showView} id="viewPopup">
                            <button className="option" id="viewTop" onClick={this.onCameraSelected}>Top</button>
                            <button className="option" id="viewFront" onClick={this.onCameraSelected}>Front</button>
                            <button className="option" id="viewReset" onClick={this.onCameraSelected}>Reset</button>
                        </div>
                    </div>
            </div>;
    }
});
