import React = require('react');

export default React.createClass<any, any>({

    getInitialState() {
        return {
            activeTab: 0
        };
    },

    render() {
        let tabs = [];
        this.props.tabs.forEach((tab, i) => {
            let className = 'main';
            if(i === this.state.activeTab) {
                className += ' selected';
            }
            tabs.push(
                <button key={tab.id} id={tab.id} onClick={this.onClick.bind(this, i, tab.callback)} className={className}>
                    <span className={tab.icon} title={tab.label}></span>
                </button>
            );
        });
        return <div className='tools' id="tabBar">
            {tabs}
        </div>;
    },

    onClick(i, cb) {
        this.state.activeTab = i;
        this.setState(this.state);
        cb();
    }
});