import React = require('react');
// import lpsService from '../services/lps-service';
import {LPSService} from 'skills-service-manager';
import marked = require('marked');
import {HTTPClient} from 'jibo-client-framework';
import {RegistrationRecord } from 'jibo-service-framework';
import {RegistryClient } from 'skills-service-manager';

import path = require('path');

let targetIndexCount = 0;

export default React.createClass<any, any>({

    getInitialState() {
        return {
            isSelected: false
        };
    },

    componentDidMount() {
    },

    showEntities() {
    },

    // opType is "backup" or "restore"
    backupOrRestore(opType:string) {
        console.log("carrying out operation: ", opType);
        RegistryClient.instance.getRecordByName('system-manager', (error, record) => {

            let opFolder:string = path.join(process.env.HOME || process.env.USERPROFILE, '.jibo', 'backup', record.name);
            console.log("folder for ", opFolder);
            // On Robot:
            // /opt/tmp/backup/<name of service>
            // http://<service address>/_M_/system/backup/
            //
            //let serviceName:string = "/opt/tmp/backup/" + record.name;
            let data = { 'directory': opFolder };

            const request = new XMLHttpRequest();
            let postString:string = '/' + opType;
            request.open('POST',  `http://${record.host}:${record.port}${postString}`, true);
            request.onreadystatechange = () => {
               if (request.readyState === 4) {
                   if (request.status === 204) {
                       console.log("POST request successful");
                   } else {
                       console.log("POST request failed");
                   }
               }
            }
            request.send(JSON.stringify(data));
        });
    },

    doBackup() {
        console.log("Doing backup!");
        this.backupOrRestore("backup");
    },

    doRestore() {
        console.log("Doing restore!");
        this.backupOrRestore("restore");
    },

    doWipe() {
        console.log("Doing wipe!");
        this.backupOrRestore("wipe");
    },

    render() {
        let paneClassName = 'advanced-pane side-pane';
        if(!this.props.isSelected) {
            paneClassName += ' hidden';
        }

        let markdown ="Backup Jibo to Cloud.\n\n";

        const labelStyle = {
            paddingBottom: '8pt',
            paddingTop: '8pt'
        }

        let showEntities = null;
        return <div className={paneClassName} ref="rightPane">
            <div className="panel-heading">
                <h2 className="target-heading">Advanced Options</h2>
            </div>
            <div
                className="instructions"
                dangerouslySetInnerHTML={{
                        __html: marked(markdown, {sanitize: true})
                    }}
            ></div>
            <label style={{labelStyle}}>Backup</label>
            <button className="btn" onClick={this.doBackup}>Do Backup</button>
            <label style={{labelStyle}}>Restore</label>
            <button className="btn" onClick={this.doRestore}>Do Restore</button>
            <label style={{labelStyle}}>Wipe</label>
            <button className="btn" onClick={this.doWipe}>Do Wipe</button>
        </div>;
    }
});
