import React = require('react');

export default React.createClass<any, any>({

    getInitialState() {
        return {
            id: this.props.target.id,
            isSelected: this.props.isSelected
        };
    },

    componentDidMount() {
        this.id = this.props.target.id;
    },

    onIdChange(event) {
        let value = event.target.value;
        this.props.setTargetId(this.props.target.id, value);
        this.setState({
            id: value
        });
    },

    onClick() {
        this.props.onClick(this.props.target.id);
    },

    onRemoveTarget() {
        this.setState({
            isSelected: true
        });
        this.props.removeTarget(this.props.target.id)
    },

    render() {
        let ray = this.props.target.parts[0].value.rays[0].dir;
        let k;
        for(k in ray) {
            ray[k] = Number(ray[k]).toFixed(5);
        }

        let className = this.props.isSelected ? "lpsTarget isSelected" : "lpsTarget unselected";
        return <div className={className} onClick={this.onClick}>
            <button className="btn remove" onClick={this.onRemoveTarget}>
                <span className="fa fa-times"></span>
            </button>
            <div className="targetId">
                <span className="title">ID:</span>
                <span className="value">{this.props.target.id}</span>
            </div>
            <div className="location">
                <span className="value x">x: {ray.x}</span>, 
                <span className="value y">y: {ray.y}</span>, 
                <span className="value z">z: {ray.z}</span>
            </div>
        </div>;
    }

});