import React = require('react');

import {ipcRenderer as ipc} from 'electron';
import {TTSService} from 'skills-service-manager';

export default React.createClass<any, any>({

    getInitialState() {
        return {
            text: "",
            speaker: this.props.speakerId
        };
    },

    componentDidMount() {
        TTSService.instance.setMode(this.props.ttsMode);
        this.inputStack = [""];
        this.inputIndex = 1;
    },

    onKeyDown(event) {
        let value = event.target.value;
        let keyCode = event.nativeEvent.keyCode;
        value = value.trim().replace(/[\|&;\$%@"#<>\(\)\+,?.]/g, "");
        if(keyCode === 13) {
            // carriage return
            this.saveInputText(value);
            this.setState({
                text: ""
            });
            this.props.onWords({words: value, final: true, speaker: this.state.speaker});
            this.props.messageHandler({words: value, speaker: this.state.speaker});
        }
        else if(keyCode === 32) {
            // space bar
            // send incremental result at each space.
            this.props.onWords({words: value, incremental: true, speaker: this.state.speaker});
        }
        // up
        else if(keyCode === 38 && this.inputIndex > 1) {
            this.inputIndex -= 1;
            this.setState({
                text: this.inputStack[this.inputIndex]
            });
        }
        // down
        else if(keyCode === 40 && this.inputIndex < this.inputStack.length) {
            this.inputIndex += 1;
            this.setState({
                text: this.inputStack[this.inputIndex]
            });
        }
    },

    // adds a new entry to undo/redo of tts stack
    // potentially very big...
    // TODO: profile this?
    saveInputText(text) {
        if(text !== this.inputStack[this.inputStack.length - 1]) {
            this.inputStack.push(text);
        }
        this.inputIndex = this.inputStack.length;
    },

    onSpeakerChange(event) {
        let value = event.target.value;
        ipc.send('set-speaker-id', value);
        this.setState({
            speaker: value
        });
    },

    setTtsMode(mode){
        if(this.state.ttsMode === mode ){
            return;
        }
        TTSService.instance.setMode(mode);
        ipc.send('set-tts-mode', mode);
    },

    setTtsModeInstant(){
        this.setTtsMode('Instant');
    },

    setTtsModeIncremental(){
        this.setTtsMode('Incremental');
    },

    onChange(event) {
        let value = event.target.value;
        let textValue = value;
        value = value.trim().replace(/[\|&;\$%@"#<>\(\)\+,?.]/g, "").toLowerCase();
        this.setState({
            text: textValue
        });
    },

    render() {
        const speakers = [<option value={''}>No ID</option>];
        this.props.loop.forEach((member) => {
            if(member.data.firstName) {
                if(this.state.speaker === member.data.memberId) {
                    speakers.push(<option selected value={member.data.memberId}>{member.data.firstName}</option>);
                }
                else {
                    speakers.push(<option value={member.data.memberId}>{member.data.firstName}</option>);
                }
            }
        });

        return <div className="asr-input">
            <span className="fa fa-comment chat-icon icon"></span>
            <input
                type="text"
                className="text text-lg chat-input"
                placeholder="Speak to Jibo here..."
                value={this.state.text}
                onChange={this.onChange}
                onKeyDown={this.onKeyDown}/>
            <div className="speaker row">
                <div className="row-label">Speaker</div>
                <div className="row-content">
                    <select name="Speaker" className="text text-md speaker-input" onChange={this.onSpeakerChange}>
                        {speakers}
                    </select>

                </div>
            </div>
            <div className="tts-mode row">
                <div className="row-label">TTS Mode</div>
                <div className="row-content">
                    <label htmlFor="dev">
                        <input
                            type="radio"
                            value="Instant"
                            id="instant"
                            className="radio"
                            checked={this.props.ttsMode === "Instant"}
                            onChange={this.setTtsModeInstant}/>
                        Instant
                    </label>
                    <label htmlFor="incremental">
                        <input
                            type="radio"
                            value="Incremental"
                            id="incremental"
                            className="radio"
                            checked={this.props.ttsMode === "Incremental"}
                            onChange={this.setTtsModeIncremental}/>
                        Incremental
                    </label>
                </div>
            </div>
        </div>;
    }
});
