function basisToPoints(x1, y1, x2, y2, x3, y3, x4, y4) {
  let m = [
    x1, x2, x3,
    y1, y2, y3,
     1,  1,  1
  ];
  let v = multmv(adj(m), [x4, y4, 1]);
  return multmm(m, [
    v[0], 0, 0,
    0, v[1], 0,
    0, 0, v[2]
  ]);
}
function general2DProjection(
  x1s, y1s, x1d, y1d,
  x2s, y2s, x2d, y2d,
  x3s, y3s, x3d, y3d,
  x4s, y4s, x4d, y4d
) {
  let s = basisToPoints(x1s, y1s, x2s, y2s, x3s, y3s, x4s, y4s);
  let d = basisToPoints(x1d, y1d, x2d, y2d, x3d, y3d, x4d, y4d);
  return multmm(d, adj(s));
}
/*function project(m, x, y) {
  let v = multmv(m, [x, y, 1]);
  return [v[0]/v[2], v[1]/v[2]];
}*/
function transform2d(elt, x1, y1, x2, y2, x3, y3, x4, y4) {
  let w = elt.offsetWidth-dims.SCREEN_EPSILON, h = elt.offsetHeight-dims.SCREEN_EPSILON;
  let t:any = general2DProjection(0, 0, x1, y1, w, 0, x2, y2, 0, h, x3, y3, w, h, x4, y4);
  for(let i = 0; i != 9; ++i) t[i] = t[i]/t[8];
  t = [t[0], t[3], 0, t[6],
       t[1], t[4], 0, t[7],
       0   , 0   , 1, 0   ,
       t[2], t[5], 0, t[8]];
  t = "matrix3d(" + t.join(", ") + ")";
  elt.style["-webkit-transform"] = t;
  elt.style["-moz-transform"] = t;
  elt.style["-o-transform"] = t;
  elt.style.transform = t;
}

function computeTransform(corners, element) {
  transform2d(element, corners[0], corners[1], corners[2], corners[3],
                   corners[4], corners[5], corners[6], corners[7]);
}
