import React = require('react');

export default React.createClass<any, any>({

    getInitialState() {
        return {};
    },

    render() {
        let wrapperClass = 'message-wrapper fade-in';
        let author:any = '';
        if(this.props.message.author === 'jibo') {
            wrapperClass += ' jibo';
        } else if (this.props.message.author) {
            author = <div className="message-speaker">{this.props.message.author}</div>;
        }
        if(this.props.message.break) {
            return <div className="message-session"></div>;
        }
        return <div className={wrapperClass}>
            {author}
            <div className='message-bubble'>
                <div className="message-content">
                    {this.props.message.content}
                </div>
            </div>
        </div>;
    }
});