import React = require('react');
import {TTSService} from 'skills-service-manager';
import MessagesList from './messages-list';
import AsrView from './asr-view';

export default React.createClass<any, any>({

    getInitialState() {
        return {
            isSelected: false
        };
    },

    componentDidMount() {
        this.chatProxy = this.props.chatProxy;
        TTSService.instance.on('speech', (text) => {
            this.messageHandler({words: text, speaker: 'jibo'});
        });
        TTSService.instance.on('token', (text) => {
            this.incrementalMessageHandler(text);
        });
        // TODO: update this to not act differently in service based on mode!!!
        TTSService.instance.on('sending-tokens', () => {
            this.addMessage({
                content: '',
                author: 'jibo'
            });
        });
        TTSService.instance.on('stop', () => {
            this.addMessage({
                content: '',
                author: 'jibo'
            });
        });
        window.addEventListener('resize', () => {
          this.forceUpdate();
        });
    },

    incrementalMessageHandler(text) {
        let currMessages = this.refs.messagesList.state.messages
        if(currMessages[currMessages.length-1].author !== 'jibo') {
            this.refs.messagesList.addMessage({author: 'jibo', content: ""});
        }
        this.refs.messagesList.appendMessage(text);
    },

    messageHandler(message) {
        this.addMessage({
            content: message.words,
            author: message.speaker
        });

        this.props.onWords(message);
    },

    addMessage(message) {
        if (message) {
            message.date = new Date();
            this.refs.messagesList.addMessage(message);
        }
    },

    render() {
        let paneClassName = 'chat-pane side-pane';
        if(!this.props.isSelected) {
            paneClassName += ' hidden';
        }
        return <div className={paneClassName} ref="root">
            <MessagesList ref="messagesList" reloadWatcher={this.props.reloadWatcher}/>
            <AsrView
                ref="AsrView"
                ttsMode={this.props.ttsMode}
                speakerId={this.props.speakerId}
                loop={this.props.loop}
                messageHandler={this.messageHandler}
                onWords={this.props.onWords}>
            </AsrView>
        </div>;
    }
});
