/*
 * This is the entry point of the simulator app
 */
import React = require('react');
import {
    ASRService,
    LPSService,
    BodyService,
    GlobalListen
} from 'skills-service-manager';
import ChatView from './views/chat-view';
import LpsView from './views/lps-view';
import AdvancedView from './views/advanced-view';
import TabBar from './react-components/tab-bar';
import {EventEmitter} from 'events';
import {RegistryClient, Factory, KBService} from 'skills-service-manager';
import Notifications from './views/notifications-view';
import {JiboConfig, RobotInfo, visualize} from "animation-utilities";
import {KnowledgeBase} from 'jibo-kb';

const kb = new KnowledgeBase();

const resolve = require('resolve');
//import findRoot = require('find-root');
//import path = require('path');

//require('./elements/custom-elements');

import faceOnBody from './face-on-body';
// import motorService from './services/motor-service';
import dims from './dimensions';
import async = require('async');
import path = require('path');

import {ipcRenderer as ipc} from 'electron';

// This is to prevent a bug where jibo-tools and skills-service-manager end up sharing the same animation-utilities,
// this causes issues as jibo's wrapVisualize changes the signature of visualize.createRobotRenderer by dropping the
// the robotInfo parameter.
// See: https://github.jibo.com/sdk/jibo/blob/079e5a50fafc27b26556687b2b8f339ea214560c/src/utils/AnimationUtils.js#L77-L98
const createRobotRenderer = visualize.createRobotRenderer;

let previousSettings, settings;

// TODO:
/*
    - persist names/chat history
    - replay convos
    - wav as audio files
    - make scrolling work
    - auto keyboard focus
*/

let isRemoteMode = ipc.sendSync('is-remote-mode') === "true";
if(isRemoteMode){
    dims.CHAT_WIDTH = 0;
}

// The last GL instance we subscribed to for HJ events which we use to
// simulate the localized HJ entities in the LPS stream.
// This is needed to successfully re-subscribe to new GL instance after skill reload
let lastGLInstance;

/*let View = */
let View = React.createClass<any, any>({
    getInitialState() {
        return {
            currentView: 'chat'
        };
    },

    componentWillMount() {
        this.reloadWatcher = new EventEmitter();

        previousSettings = settings = JSON.parse(ipc.sendSync('get-simulator-settings'));
    },

    render() {
        let tabs = [
            {
                label: 'Chat',
                id: 'chatTab',
                icon: "icon fa fa-comment",
                callback: (() => {this.setState({
                        currentView: 'chat'
                    });
                })
            },
            {
                label: 'LPS',
                id: 'lpsTab',
                icon: "icon fa fa-compass",
                callback: (() => {this.setState({
                        currentView: 'lps'
                    });
                })
            },
            {
                label: 'Advanced',
                id: 'advancedTab',
                icon: "icon fa fa-cog",
                callback: (() => {this.setState({
                        currentView: 'advanced'
                    });
                })
            }
        ];

        let isChat = (this.state.currentView === 'chat');
        let isLps = (this.state.currentView === 'lps');
        let isAdvanced = (this.state.currentView === 'advanced');

        if(!isRemoteMode) {
            let tabView, chatView, lpsView, advancedView;
            tabView = <TabBar tabs={tabs}/>;
            chatView = <ChatView ref="chat" loop={this.props.loop} speakerId={settings.speakerId} ttsMode={settings.ttsMode} onWords={this.onWords} isSelected={isChat} reloadWatcher={this.reloadWatcher}/>;
            lpsView = <LpsView ref="lps"
                               isSelected={isLps}
                               robotRenderer={this.robotRenderer}
                               parent={this}
                               visualizer={this.visualizer}
                               updateTargets={this.forceUpdate.bind(this)}/>;
            advancedView = <AdvancedView ref="advanced" isSelected={isAdvanced}/>;
            return <div>
                {tabView}
                {chatView}
                {lpsView}
                {advancedView}
            </div>;
        } else {
            return <div></div>;
        }

    },

    getVisualizerContainer() {
        return this.visualizer;
    },

    getRobotRenderer() {
        return this.robotRenderer;
    },

    componentDidMount() {
        if(LPSService.instance) {
            LPSService.instance.on('update', (/*target*/) => {
                this.forceUpdate();
            });

        }

        // Listen for changes to the devTools visibility state
        let counter = 0;
        let onSettingsChanged = (_previousSettings, newSettings) => {
                previousSettings = _previousSettings;
                settings = newSettings;

                // Force a redraw so any component that uses the settings can redraw
                if(previousSettings.ttsMode !== settings.ttsMode) {
                    if(counter < 20){
                        counter++;
                        this.forceUpdate();
                    }
                }
            };

        // Get the jibo container
        const container = document.getElementById('container');
        const face = document.getElementById('face');
        const visualizer = document.getElementById('visualizer');
        const skillWebview = document.getElementById('skill');

        this.visualizer = visualizer;

        faceOnBody.init(this.props.robotInfo, createRobotRenderer, container, face, visualizer, onSettingsChanged, (err, robotRenderer, _settings) => {
            settings = _settings;

            // Display the loader screen on top of the webview until it's ready
            // loader.style.visibility = "visible";
            face.className = "loading";

            ipc.on('reload-skill', () => {
                (skillWebview as any).reloadIgnoringCache();
            });

            skillWebview.addEventListener('did-start-loading', () => {
                face.className = "loading";

                this.reloadWatcher.emit('reload');

                // HACK: This is work around for an issue that we can't explain where initially the webview content
                // is all white until you do something that creates a resize of sorts
                webviewWhiteScreenWorkaround(skillWebview);
            });

            // Get the skill's path and then load it into the webview that it will run in it
            this.robotRenderer = robotRenderer;

            // Listen for the main process gets a user command (keypress or menu) to toggle the dev tool of the skill
            let ignoreNextDevToolsClosedEvent = false;
            ipc.on('toggle-dev-tools', (sender, showDevTools) => {
                if(showDevTools){
                    (skillWebview as any).openDevTools();
                }
                else {
                    ignoreNextDevToolsClosedEvent = true;
                    (skillWebview as any).closeDevTools();
                }
            });

            skillWebview.addEventListener('devtools-closed', () => {
                if(ignoreNextDevToolsClosedEvent){
                    ignoreNextDevToolsClosedEvent = false;
                    return;
                }
                //console.warn('devtools-closed');
                ipc.send('close-dev-tools');
            });

            const onDomReady = () => {
                // Restore state of devtools visibility
                if( !(skillWebview as any).isDevToolsOpened() && settings.isDevToolsOpened ){
                    (skillWebview as any).openDevTools();
                }
                else if( (skillWebview as any).isDevToolsOpened() && !settings.isDevToolsOpened ){
                    (skillWebview as any).closeDevTools();
                }

                // Inject a few default body properties
                (skillWebview as any).insertCSS('html{min-width: 1280px; min-height: 720px;} body{min-width: 1280px; min-height: 720px; margin: 0px; overflow: hidden;}');
                skillWebview.addEventListener('devtools-closed', () => {
                    if(ignoreNextDevToolsClosedEvent){
                        ignoreNextDevToolsClosedEvent = false;
                        return;
                    }
                    //console.warn('devtools-closed');
                    ipc.send('close-dev-tools');
                });

                // Hide loader screen now
                face.className = "";

                // Fake HJ audio entity based on SSM-GL HJ event
                if (!lastGLInstance || lastGLInstance !== GlobalListen.getInstance()) {
                    lastGLInstance = GlobalListen.getInstance();
                    GlobalListen.getInstance().events.listen.hjHeard.on(() => {
                        LPSService.instance.triggerSimulatedHJEvent();
                    });
                }
            };

            // Listen for when the skill's page's dom is ready, then show the webview
            skillWebview.addEventListener("dom-ready", onDomReady);

            if(BodyService.instance) {
                // Start loop that updates the visualizer
                BodyService.instance.on('update', (dofs) => {
                    robotRenderer.display(dofs);
                });
            }
            (skillWebview as any).src = ipc.sendSync('get-skill-path');
        });

    },

    onWords(wordOptions) {
        ASRService.instance.onWordsReceived(wordOptions);
    }

});

async.series([
    (next) => {
        if( !isRemoteMode ){
            // get the root directory for the SSM. this changed due to the lerna mono repo restructing
            let rootDir = path.join(resolve.sync('skills-service-manager', { basedir: __dirname }), '..');
            let factory = new Factory({
                RegistryService: {
                    host: '127.0.0.1',
                    port: 0
                },
                services: {
                    KBService: {
                        port: 0
                    },
                    TTSService: {
                        port: 0
                    },
                    LPSService: {
                        port: 0
                    },
                    ASRService: {
                        port: 0
                    },
                    ListenService: {
                        port: 0
                    },
                    GlobalManagerService: {
                        port: 0
                    },
                    BodyService: {
                        port: 0
                    },
                    ErrorService: {
                        port: 0
                    },
                    SystemMonitoringServiceSim: {
                        port: 0
                    },
                    NLUService: {
                        port: 0
                    },
                    NotificationsService: {
                        port: 0
                    },
                    MediaService: {
                        port: 0
                    },
                    MediaManagerService: {
                        port: 0
                    },
                    ServerService: {
                        port: 0
                    },
                    SystemManagerService: {
                        port: 0
                    },
                    SchedulerService: {
                        port: 0
                    },
                    SkillsServiceSim: {
                        port: 0,
                        skillsBaseDir: path.join(ipc.sendSync('get-skill-path'), '..')
                    }
                }
            }, rootDir);
            factory.init(() => {
                const registryServiceURL = `http://127.0.0.1:${RegistryClient.instance.port}/registry`;
                ipc.send('registry-init', registryServiceURL);
                //console.log("Registry Service URL: " + registryServiceURL);
                next();
            });
        } else {
            ipc.send('registry-init', 'http://127.0.0.1:8181');
            next();
        }
    },
    (next) => {
        kb.init({
            host: '127.0.0.1',
            port: KBService.instance.port
        }, () => {
            kb.initLoop();
            kb.initMedia();
            next();
        });
    },
    (next) => {
        kb.loop.loadLoop((err, members) => {
            if(err) {
                members = [];
            }
            let config = new JiboConfig();
            RobotInfo.createInfo(config,  (robotInfo) => {
                React.render(
                    <View robotInfo={robotInfo} asrService={ASRService.instance} loop={members}/>,
                    document.getElementById('sidebar')
                );

                React.render(
                    <Notifications/>,
                    document.getElementById('notifications')
                );

                next();
            });

        });
    }
], function(err){
    if(err){
        console.error(`Simulator: ${err}`);
    }
});


/*
 * This all basically simulates the manuel workaround we had before to get rid of the white screen
 * issue on first loading the simulator. We will be talking to Electron/Github to get a proper
 * solution going.
 */
function webviewWhiteScreenWorkaround(webview) {
    webview.style.width = "0px";
    webview.style.height = "0px";

    webview.addEventListener("did-finish-load", function() {
        webview.style.width = "1280px";
        webview.style.height = "720px";
    });
}
